fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // Since we assume arr1 and arr2 have the same length and arr2 has no zeros,
    // we can safely zip and perform the modulo operation element-wise.
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a % b)
        .collect()
}

